import React, { useState, useEffect, useRef } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';

/* Import App.css to inherit global styles (Header, Main, Footer, Gradient) */
import '../App.css';
import "./EstiloInicio.css";

import { useNavigate } from 'react-router-dom';
import Productos from './Productos';
import Calculos from './CalculosInic';
import Botones from './BotonesInic';
import { logout, getUsuario } from '../services/api';

function Inicio() {
    const navigate = useNavigate();
    const usuario = getUsuario();

    const {
        productosIniciales,
        productos,
        setProductos
    } = Productos();
    const menuRef = useRef(null);

    const [filtro, setFiltro] = useState('todo');
    const [modoOscuro, setModoOscuro] = useState(false);
    const [menuAbierto, setMenuAbierto] = useState(false);
    const [idioma, setIdioma] = useState('es');
    const [tema, setTema] = useState('oscuro');
    const [mostrarPreferencias, setMostrarPreferencias] = useState(false);

    const textos = {
        es: {
            titulo: 'CaffES App',
            menu: 'Menú',
            todo: 'Todo',
            comida: 'Comida',
            bebida: 'Bebida',
            resumen: 'Resumen',
            vacio: 'Su pedido está vacío',
            total: 'Total',
            confirmar: 'Confirmar',
            limpiar: 'Limpiar',
            salir: 'Salir',
            preferencias: 'Preferencias',
            cerrarSesion: 'Cerrar Sesión',
            tema: 'Tema',
            idioma: 'Idioma',
            claro: 'Claro',
            oscuro: 'Oscuro',
            espanyol: 'Español',
            ingles: 'Inglés',
            cerrar: 'Cerrar',
            nombresProductos: {
                'Agua': 'Agua Mineral',
                'Refresco': 'Refresco Frío',
                'Croissant': 'Croissant Mixto',
                'Ensalada': 'Ensalada César',
                'Hamburguesa': 'Burger Completa',
                'Perrito': 'Hot Dog Especial',
                'Sandwich': 'Sandwich Club',
                'Postre': 'Tarta Casera',
                'Paquete de papas': 'Papas Fritas'
            }
        },
        en: {
            titulo: 'CaffES App',
            menu: 'Menu',
            todo: 'All',
            comida: 'Food',
            bebida: 'Drinks',
            resumen: 'Summary',
            vacio: 'Your order is empty',
            total: 'Total',
            confirmar: 'Confirm',
            limpiar: 'Clear',
            salir: 'Exit',
            preferencias: 'Preferences',
            cerrarSesion: 'Logout',
            tema: 'Theme',
            idioma: 'Language',
            claro: 'Light',
            oscuro: 'Dark',
            espanyol: 'Spanish',
            ingles: 'English',
            cerrar: 'Close',
            nombresProductos: {
                'Agua': 'Mineral Water',
                'Refresco': 'Cold Soda',
                'Croissant': 'Mixed Croissant',
                'Ensalada': 'Caesar Salad',
                'Hamburguesa': 'Classic Burger',
                'Perrito': 'Special Hot Dog',
                'Sandwich': 'Club Sandwich',
                'Postre': 'Homemade Cake',
                'Paquete de papas': 'French Fries'
            }
        }
    };

    const t = textos[idioma];

    const tradNombre = (nombreOriginal) => {
        return t.nombresProductos[nombreOriginal] || nombreOriginal;
    };

    const {
        calcularVentasProducto,
        calcularVentasTotales,
        calcularImpuesto,
        calcularTotalConImpuesto
    } = Calculos({ productos });

    const {
        aumentarCantidad,
        disminuirCantidad,
        reiniciarTodo
    } = Botones({ productos, productosIniciales, setProductos })

    const alternarModo = () => {
        setModoOscuro(!modoOscuro);
    };

    const handleLogout = () => {
        logout();
        navigate('/');
    };

    const productosFiltrados = filtro === 'todo'
        ? productos
        : productos.filter(p => p.categoria === filtro);

    const Dinero = (valor) => {
        return valor + '€';
    };

    const productosConPedidos = productos.filter(p => p.cantidad > 0);
    const hayPedidos = productosConPedidos.length > 0;

    useEffect(() => {
        const handleClickAfuera = (event) => {
            if (menuRef.current && !menuRef.current.contains(event.target)) {
                setMenuAbierto(false);
            }
        };
        document.addEventListener('mousedown', handleClickAfuera);
        return () => document.removeEventListener('mousedown', handleClickAfuera);
    }, []);

    return (
        /* Use the 'App' class to get the main container style */
        <div className={`App ${tema === 'claro' ? 'app-claro' : ''}`}>

            {/* Standard App Header */}
            <header className="App-header">
                <div className="header-container">
                    <div className="title">{t.titulo}</div>

                    <div className="header-right">
                        <div className="user-menu-wrapper" ref={menuRef}>
                            <div
                                className={`user-profile ${menuAbierto ? 'active' : ''}`}
                                onClick={() => setMenuAbierto(!menuAbierto)}
                            >
                                <span className="user-icon"></span>
                                <span className="user-name">{usuario?.nombre || 'Usuario'}</span>
                                <span className="chevron">▼</span>
                            </div>

                            {menuAbierto && (
                                <div className="user-dropdown shadow-lg">
                                    <button
                                        className="dropdown-item"
                                        onClick={() => {
                                            setMostrarPreferencias(true);
                                            setMenuAbierto(false);
                                        }}
                                    >
                                        <span className="item-icon">⚙️</span>
                                        {t.preferencias}
                                    </button>
                                    <button className="dropdown-item logout" onClick={handleLogout}>
                                        {t.cerrarSesion}
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </header>

            {/* Modal de Preferencias */}
            {mostrarPreferencias && (
                <div className="prefs-overlay">
                    <div className="prefs-modal shadow-lg">
                        <h3>{t.preferencias}</h3>

                        <div className="prefs-section">
                            <label>{t.tema}</label>
                            <div className="btn-group-toggle">
                                <button
                                    className={tema === 'claro' ? 'active' : ''}
                                    onClick={() => setTema('claro')}
                                >
                                    {t.claro} ☀️
                                </button>
                                <button
                                    className={tema === 'oscuro' ? 'active' : ''}
                                    onClick={() => setTema('oscuro')}
                                >
                                    {t.oscuro} 🌙
                                </button>
                            </div>
                        </div>

                        <div className="prefs-section">
                            <label>{t.idioma}</label>
                            <div className="btn-group-toggle">
                                <button
                                    className={idioma === 'es' ? 'active' : ''}
                                    onClick={() => setIdioma('es')}
                                >
                                    {t.espanyol} 🇪🇸
                                </button>
                                <button
                                    className={idioma === 'en' ? 'active' : ''}
                                    onClick={() => setIdioma('en')}
                                >
                                    {t.ingles} 🇬🇧
                                </button>
                            </div>
                        </div>

                        <button className="btn-confirm-prefs" onClick={() => setMostrarPreferencias(false)}>
                            {t.cerrar}
                        </button>
                    </div>
                </div>
            )}

            <main className="App-main">
                <div className="dashboard-container">

                    <div className="row g-4">
                        <div className="col-lg-8">
                            {/* Filtros de Categoría */}
                            <div className="filter-container mb-4">
                                <button
                                    className={`btn-filter ${filtro === 'todo' ? 'active' : ''}`}
                                    onClick={() => setFiltro('todo')}
                                >
                                    Todo
                                </button>
                                <button
                                    className={`btn-filter ${filtro === 'comida' ? 'active' : ''}`}
                                    onClick={() => setFiltro('comida')}
                                >
                                    Comida 🍔
                                </button>
                                <button
                                    className={`btn-filter ${filtro === 'bebida' ? 'active' : ''}`}
                                    onClick={() => setFiltro('bebida')}
                                >
                                    Bebida 🥤
                                </button>
                            </div>

                            <h2 className="text-white mb-4 border-bottom pb-2">Menú</h2>
                            <div className="row g-3">
                                {productosFiltrados.map(producto => (
                                    <div className="col-6 col-md-4 col-xl-3" key={producto.id}>
                                        <div className="dash-card">
                                            <div className="icon-wrapper">
                                                {producto.nombre === 'Agua' && '💧'}
                                                {producto.nombre === 'Refresco' && '🥤'}
                                                {producto.nombre === 'Croissant' && '🥐'}
                                                {producto.nombre === 'Ensalada' && '🥗'}
                                                {producto.nombre === 'Hamburguesa' && '🍔'}
                                                {producto.nombre === 'Perrito' && '🌭'}
                                                {producto.nombre === 'Sandwich' && '🥪'}
                                                {producto.nombre === 'Postre' && '🍰'}
                                                {producto.nombre === 'Paquete de papas' && '🍟'}
                                            </div>
                                            <h3 className="item-name">{tradNombre(producto.nombre)}</h3>
                                            <div className="item-price">{Dinero(producto.precio)}</div>

                                            <div className="control-group">
                                                <button
                                                    className="btn btn-round"
                                                    onClick={() => disminuirCantidad(producto.id)}
                                                    disabled={producto.cantidad === 0}
                                                >
                                                    -
                                                </button>
                                                <span className="qty-badge">{producto.cantidad}</span>
                                                <button
                                                    className="btn btn-round"
                                                    onClick={() => aumentarCantidad(producto.id)}
                                                >
                                                    +
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Right Column: Summary Panel */}
                        <div className="col-lg-4">
                            <div className="summary-panel shadow-lg">
                                <h2 className="summary-title">{t.resumen}</h2>

                                <div className="flex-grow-1">
                                    {hayPedidos ? (
                                        productosConPedidos.map(producto => (
                                            <div key={producto.id} className="order-item">
                                                <div>
                                                    <span className="fw-bold text-warning me-2">{producto.cantidad}x</span>
                                                    {tradNombre(producto.nombre)}
                                                </div>
                                                <div>{Dinero(calcularVentasProducto(producto))}</div>
                                            </div>
                                        ))
                                    ) : (
                                        <div className="text-center py-5 text-white-50">
                                            <div className="fs-1 mb-2">🛒</div>
                                            <p>{t.vacio}</p>
                                        </div>
                                    )}
                                </div>

                                {hayPedidos && (
                                    <div className="totals-section mt-3">
                                        <div className="d-flex justify-content-between mb-1">
                                            <span>Subtotal:</span>
                                            <span>{Dinero(calcularVentasTotales())}</span>
                                        </div>
                                        <div className="d-flex justify-content-between mb-2">
                                            <span>IGIC (7%):</span>
                                            <span>{Dinero(calcularImpuesto())}</span>
                                        </div>
                                        <div className="d-flex justify-content-between fw-bold fs-5 text-warning border-top pt-2">
                                            <span>{t.total}:</span>
                                            <span>{Dinero(calcularTotalConImpuesto())}</span>
                                        </div>
                                    </div>
                                )}

                                <div className="mt-4">
                                    <button
                                        className="btn-confirm"
                                        onClick={() => {
                                            const total = calcularTotalConImpuesto();
                                            if (total > 0) alert('Pedido confirmado. Total: ' + Dinero(total));
                                            else alert('Pedido vacío.');
                                        }}
                                    >
                                        {t.confirmar}
                                    </button>

                                    <button className="btn-clear" onClick={reiniciarTodo}>
                                        {t.limpiar}
                                    </button>

                                    <button
                                        className="btn-exit"
                                        onClick={() => { if (window.confirm('¿Salir?')) window.location.href = '/' }}
                                    >
                                        {t.salir}
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>

            {/* Standard App Footer */}
            <footer className="App-footer">
                <div>© IES José Zerpa - Cafetería</div>
            </footer>
        </div>
    )
}

export default Inicio
